const expected=$('OPURO — Preparar etiquetas v1.13').all().length;
const state=$getWorkflowStaticData('global');
const executionId=String($execution.id ?? 'execution');
const resultKey=`opmx_tag_results:${executionId}:opuro`;
const rows=(Array.isArray(state[resultKey]) ? state[resultKey] : [])
  .filter(x=>Number(x?.tag_id)>0)
  .sort((a,b)=>Number(a.tag_index)-Number(b.tag_index));

if(rows.length!==expected){
  throw new Error(`Etiquetas incompletas: esperadas ${expected}, resueltas ${rows.length}.`);
}

const ids=[];
const seen=new Set();
for(const row of rows){
  const id=Number(row.tag_id);
  if(!seen.has(id)){
    seen.add(id);
    ids.push(id);
  }
}

delete state[resultKey];

return [{json:{
  tag_ids:ids,
  tags_resolved:rows,
  tags_count:ids.length
}}];

const req = $('OPURO — Preparar etiquetas v1.13').item.json;
const rawEnvelope = $json ?? {};
let raw = rawEnvelope?.body ?? rawEnvelope?.data ?? rawEnvelope;
let body = raw;

const MAX_ATTEMPTS = 6;
const state = $getWorkflowStaticData('global');
const executionId = String($execution.id ?? 'execution');
const stateKey = `opmx_tag_retry:${executionId}:opuro:${req.tag_index}:${req.tag_slug}`;
const previousAttempt = Number(state[stateKey] ?? 0);
const attempt = previousAttempt + 1;

function rawText(v) {
  if (typeof v === 'string') return v.trim();
  try { return JSON.stringify(v); } catch (_) { return String(v ?? '').trim(); }
}
const text = rawText(raw);

const explicitStatus = Number(
  rawEnvelope?.statusCode ??
  rawEnvelope?.status ??
  rawEnvelope?.httpCode ??
  rawEnvelope?.response?.statusCode ??
  rawEnvelope?.response?.status ??
  body?.statusCode ??
  0
);

const transientByStatus = [429,502,503,504].includes(explicitStatus);
const transientByMessage =
  /Service Unavailable|Bad Gateway|Gateway Timeout|Too Many Requests/i.test(text);

const transient = transientByStatus || transientByMessage;

if (transient) {
  const status = transientByStatus
    ? explicitStatus
    : (/Too Many Requests/i.test(text) ? 429
      : /Bad Gateway/i.test(text) ? 502
      : /Gateway Timeout/i.test(text) ? 504
      : 503);

  if (attempt >= MAX_ATTEMPTS) {
    delete state[stateKey];
    throw new Error(
      `WordPress/Hostinger siguió devolviendo ${status} después de ${attempt} intentos ` +
      `al asegurar la etiqueta "${req.tag_name}" (${req.tag_slug}). ` +
      `Última respuesta: ${text.slice(0, 500)}`
    );
  }

  state[stateKey] = attempt;
  const waitSeconds = Math.min(3 * Math.pow(2, attempt - 1), 48);

  return {
    json: {
      tag_index:Number(req.tag_index),
      tag_name:req.tag_name,
      tag_slug:req.tag_slug,
      __tag_retry:true,
      __tag_retry_attempt:attempt,
      __tag_retry_status:status,
      __tag_retry_wait_seconds:waitSeconds,
      __tag_retry_preview:text.slice(0,300)
    }
  };
}

delete state[stateKey];

if (typeof raw === 'string') {
  if (!text) {
    throw new Error(`WordPress devolvió una respuesta vacía al asegurar la etiqueta "${req.tag_name}" (${req.tag_slug}).`);
  }
  try {
    body = JSON.parse(text);
  } catch (e) {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try { body = JSON.parse(text.slice(start, end + 1)); }
      catch (_) {
        throw new Error(`WordPress devolvió una respuesta no JSON al asegurar "${req.tag_name}" (${req.tag_slug}). Respuesta: ${text.slice(0,500)}`);
      }
    } else {
      throw new Error(`WordPress devolvió una respuesta no JSON al asegurar "${req.tag_name}" (${req.tag_slug}). Respuesta: ${text.slice(0,500)}`);
    }
  }
}

let id = Number(body?.id || 0);
let action = 'CREATED';

if (!id && body?.code === 'term_exists') {
  id = Number(body?.data?.term_id ?? body?.data?.term_exists ?? body?.term_id ?? 0);
  action = 'EXISTING';
}

if (!id) {
  throw new Error(
    `No se pudo asegurar la etiqueta "${req.tag_name}" (${req.tag_slug}). ` +
    `Respuesta WordPress: ${JSON.stringify(body)}`
  );
}

const result = {
  tag_index:Number(req.tag_index),
  tag_name:req.tag_name,
  tag_slug:req.tag_slug,
  tag_id:id,
  action,
  attempts:attempt,
  __tag_retry:false
};

const resultKey = `opmx_tag_results:${executionId}:opuro`;
if (!Array.isArray(state[resultKey])) state[resultKey] = [];
state[resultKey] = state[resultKey].filter(x => Number(x.tag_index) !== Number(result.tag_index));
state[resultKey].push(result);

return {json:result};

const c=$('Validar y normalizar OPMX MASTER').first().json.canonical;
const tags=Array.isArray(c.tags)?c.tags.map(x=>String(x).trim()).filter(Boolean):[];
if(!tags.length) throw new Error('SEO.ETIQUETAS está vacío.');

const norm=s=>String(s??'')
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .trim().toLocaleLowerCase('es-MX');

const slugify=s=>norm(s)
  .replace(/[^a-z0-9]+/g,'-')
  .replace(/^-+|-+$/g,'');

const seen=new Set();
const out=[];

for(const name of tags){
  const key=norm(name);
  if(!key || seen.has(key)) continue;
  seen.add(key);
  out.push({json:{
    tag_index:out.length,
    tag_name:name,
    tag_slug:slugify(name)
  }});
}
return out;

