const c=$('Validar y normalizar OPMX MASTER').first().json.canonical;
const requested=String(c.categories?.opuro?.principal ?? c.category ?? '').trim();
if(!requested) throw new Error('El JSON MASTER no entregó la categoría principal para OPURO.');

const norm=s=>String(s??'')
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .replace(/\s+/g,' ')
  .trim().toLocaleLowerCase('es-MX');

const rows=$input.all().map(i=>i.json).flatMap(x=>Array.isArray(x)?x:[x]);
const exact=rows.find(x=>norm(x.name)===norm(requested));

if(!exact?.id){
  const available=rows.map(x=>`${x.name??'(sin nombre)'} [slug ${x.slug??'?'} | ID ${x.id??'?'}]`).join(', ');
  throw new Error(`La categoría "${requested}" no existe como coincidencia exacta por nombre en Oxígeno Puro. Categorías recibidas de WordPress: ${available||'ninguna'}.`);
}
return [{json:{
  category_id:Number(exact.id),
  category_name:exact.name,
  category_slug:exact.slug??null,
  requested_category:requested,
  resolution:'EXACT_NORMALIZED_NAME_MATCH'
}}];

let envelope = $json.body ?? $json;

const destinoRaw = String(envelope.CREAR_EN ?? '').trim().toUpperCase();
const destinosValidos = ['OPURO','OPOL','AMBOS'];
if (!destinosValidos.includes(destinoRaw)) {
  throw new Error(`CREAR_EN inválido o ausente. Valor recibido: "${destinoRaw}". Usa OPURO, OPOL o AMBOS.`);
}
const publicarRaw = envelope.PUBLICAR;
const publish = Array.isArray(publicarRaw)
  ? publicarRaw.length > 0
  : (publicarRaw === true || ['sí','si','true','1','on'].includes(String(publicarRaw ?? '').trim().toLowerCase()));
const execution = {
  destination: destinoRaw,
  create_opuro: destinoRaw === 'OPURO' || destinoRaw === 'AMBOS',
  create_opol: destinoRaw === 'OPOL' || destinoRaw === 'AMBOS',
  publish
};

// v1.1.7: el MASTER llega pegado en "json" O como archivo "json_file".
const pastedJson = typeof envelope.json === 'string' ? envelope.json.trim() : '';
const binary = $input.item.binary ?? {};
const binaryKeys = Object.keys(binary);
const fileKey = binary.json_file ? 'json_file' : (binaryKeys.length === 1 ? binaryKeys[0] : null);
const hasFile = Boolean(fileKey);

if (pastedJson && hasFile) {
  throw new Error('Entrega el OPMX MASTER de una sola forma: pega el JSON en el cuadro de texto O sube el archivo .json, no ambos.');
}
if (!pastedJson && !hasFile) {
  throw new Error('Falta el OPMX MASTER. Pega el JSON completo en el cuadro de texto o sube un archivo .json.');
}

let d;
if (hasFile) {
  const meta = binary[fileKey] ?? {};
  const fileName = String(meta.fileName ?? '').trim();
  const extension = String(meta.fileExtension ?? '').trim().toLowerCase();
  if (fileName && !/\.json$/i.test(fileName) && extension !== 'json') {
    throw new Error(`El archivo subido debe ser .json. Archivo recibido: ${fileName || '(sin nombre)'}`);
  }

  let fileText;
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, fileKey);
    fileText = buffer.toString('utf8').replace(/^\uFEFF/, '').trim();
  } catch (error) {
    throw new Error(`No fue posible leer el archivo JSON subido: ${error.message}`);
  }
  if (!fileText) throw new Error('El archivo JSON subido está vacío.');

  try { d = JSON.parse(fileText); }
  catch (error) { throw new Error(`El archivo subido no contiene JSON válido: ${error.message}`); }
} else {
  try { d = JSON.parse(pastedJson); }
  catch (error) { throw new Error(`El campo "json" no contiene JSON válido: ${error.message}`); }
}

if (typeof d === 'string') {
  try { d = JSON.parse(d.trim()); }
  catch (error) { throw new Error(`El OPMX MASTER recibido no contiene JSON válido: ${error.message}`); }
}

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}
function arr(v) {
  if (Array.isArray(v)) return v.map(x => str(x)).filter(Boolean);
  if (typeof v === 'string' && v.trim()) return v.split(',').map(x => x.trim()).filter(Boolean);
  return [];
}
function imageSlugFromUrl(url, label) {
  if (!url) return '';
  try {
    const cleanUrl = String(url).split('?')[0].split('#')[0];
    const filename = decodeURIComponent(cleanUrl.substring(cleanUrl.lastIndexOf('/') + 1));
    return filename.replace(/\.[a-zA-Z0-9]+$/, '').trim();
  } catch (error) {
    throw new Error(`No fue posible obtener el nombre de archivo desde ${label}: ${url}`);
  }
}

const SEO = d.SEO ?? d.seo ?? {};
const PUB = d.PUBLICACION ?? d.publication ?? {};
// Contrato v1.2: AUTOR_ID está prohibido en el MASTER.
// La identidad técnica del autor pertenece al Publisher.
const forbiddenAuthorFields = [
  ['PUBLICACION.AUTOR_ID', PUB.AUTOR_ID],
  ['PUBLICACION.author_id', PUB.author_id],
  ['AUTOR_ID', d.AUTOR_ID],
  ['author_id', d.author_id]
].filter(([, value]) => value !== undefined && value !== null);

if (forbiddenAuthorFields.length) {
  throw new Error(
    'CONTRATO_V1_2_AUTOR_ID_PROHIBIDO: el MASTER no debe contener AUTOR_ID. Campos detectados: ' +
    forbiddenAuthorFields.map(([name]) => name).join(', ') + '.'
  );
}

const authorId = 3;
const authorSource = 'PUBLISHER_OPURO_REDACCION_OPMX';

const IMAGES = d.IMAGENES ?? d.images ?? {};

const HERO = IMAGES.HERO_OPURO ?? IMAGES.hero_opuro ?? {};
const FEATURED_OPURO = IMAGES.DESTACADA_OPURO ?? IMAGES.featured_opuro ?? {};
const FEATURED_OPOL = IMAGES.DESTACADA_OPOL ?? IMAGES.featured_opol ?? {};

const title = str(SEO.TITULO_SEO ?? d.TEXTO_EDITORIAL?.TITULO ?? d.article?.title);
const subtitle = str(SEO.SUBTITULO ?? d.TEXTO_EDITORIAL?.SUBTITULO ?? d.article?.subtitle);
const slug = str(SEO.SLUG ?? SEO.slug);
const excerpt = str(PUB.EXTRACTO ?? PUB.excerpt ?? SEO.EXTRACTO ?? SEO.excerpt ?? d.TEXTO_EDITORIAL?.ENTRADILLA);
const metaDescription = str(SEO.METADESCRIPCION ?? SEO.meta_description ?? excerpt);
const primaryKeyword = str(SEO.KEYWORD_PRINCIPAL ?? SEO.primary_keyword);
const secondaryKeywords = arr(SEO.KEYWORDS_SECUNDARIAS ?? SEO.secondary_keywords);
const keywordsAll = str(SEO.KEYWORDS_TODAS ?? SEO.keywords_todas ?? SEO.all_keywords_string);
const keywordsList = arr(SEO.KEYWORDS_TODAS_LISTA ?? SEO.keywords_todas_lista ?? SEO.KEYWORDS_TODAS ?? SEO.all_keywords);
const CATS=d.CATEGORIAS??d.categorias??{};
const OPUROCAT=CATS.OPURO??CATS.opuro??{};
const OPOLCAT=CATS.OPOL??CATS.opol??{};
const category=str(OPUROCAT.PRINCIPAL??OPUROCAT.principal??SEO.CATEGORIA??SEO.category);
const categoryOpol=str(OPOLCAT.PRINCIPAL??OPOLCAT.principal??SEO.CATEGORIA??SEO.category);
const categoryOpolSecondary=str(OPOLCAT.SECUNDARIA??OPOLCAT.secundaria)||null;
const tags = arr(SEO.ETIQUETAS ?? SEO.tags);

// v1.2.10 — PREFLIGHT BLOQUEANTE DE CONTRATO v1.2 + CATÁLOGO OPMX v1.1.
// Snapshot embebido deliberadamente: el Publisher no usa memoria ni homologa categorías entre sitios.
const CATEGORY_CATALOG = {
