  OPOL_CATEGORIES: [{"name": "CIENCIA", "parent_name": null, "parent_id": 0}, {"name": "CONGRESO", "parent_name": null, "parent_id": 0}, {"name": "DIPUTADOS", "parent_name": "CONGRESO", "parent_id": 4}, {"name": "SENADORES", "parent_name": "CONGRESO", "parent_id": 4}, {"name": "CULTURA", "parent_name": null, "parent_id": 0}, {"name": "DEPORTES", "parent_name": null, "parent_id": 0}, {"name": "ECONOMÍA", "parent_name": null, "parent_id": 0}, {"name": "EDUCACIÓN", "parent_name": null, "parent_id": 0}, {"name": "ESTADOS", "parent_name": null, "parent_id": 0}, {"name": "BAJA CALIFORNIA", "parent_name": "ESTADOS", "parent_id": 10}, {"name": "GOBIERNO", "parent_name": null, "parent_id": 0}, {"name": "INTERNACIONAL", "parent_name": null, "parent_id": 0}, {"name": "JUSTICIA", "parent_name": null, "parent_id": 0}, {"name": "MEDIO AMBIENTE", "parent_name": null, "parent_id": 0}, {"name": "MEGALÓPOLIS", "parent_name": null, "parent_id": 0}, {"name": "OPINIÓN", "parent_name": null, "parent_id": 0}, {"name": "POLÍTICA", "parent_name": null, "parent_id": 0}, {"name": "TECNOLOGÍA", "parent_name": null, "parent_id": 0}, {"name": "TURISMO", "parent_name": null, "parent_id": 0}, {"name": "Uncategorized", "parent_name": null, "parent_id": 0}]
};

const CONTROL = d.CONTROL_EDITORIAL ?? d.control_editorial ?? {};
const controlEstado = str(CONTROL.ESTADO ?? CONTROL.estado).toUpperCase();

if (controlEstado !== 'LISTO') {
  throw new Error(
    `CONTROL_EDITORIAL_NO_LISTO: el Publisher sólo admite paquetes con CONTROL_EDITORIAL.ESTADO = LISTO. Valor recibido: "${controlEstado || '(vacío)'}".`
  );
}

if (!category) {
  throw new Error('CATEGORIA_OPURO_NO_AUTORIZADA: falta CATEGORIAS.OPURO.PRINCIPAL.');
}
if (!CATEGORY_CATALOG.OPURO_ALLOWED.includes(category)) {
  throw new Error(
    `CATEGORIA_OPURO_NO_AUTORIZADA: "${category}" no existe literalmente en sites.OPURO.allowed_names del catálogo OPMX v${CATEGORY_CATALOG.schema_version}. No se enviará nada a WordPress.`
  );
}

if (!categoryOpol) {
  throw new Error('CATEGORIA_OPOL_NO_AUTORIZADA: falta CATEGORIAS.OPOL.PRINCIPAL.');
}
if (!CATEGORY_CATALOG.OPOL_ALLOWED.includes(categoryOpol)) {
  throw new Error(
    `CATEGORIA_OPOL_NO_AUTORIZADA: "${categoryOpol}" no existe literalmente en sites.OPOL.allowed_names del catálogo OPMX v${CATEGORY_CATALOG.schema_version}. No se enviará nada a WordPress.`
  );
