};
heroOpuro.slug = '';

const featuredOpuro = {
  url: str(FEATURED_OPURO.URL ?? FEATURED_OPURO.url),
  alt_text: str(FEATURED_OPURO.ALT ?? FEATURED_OPURO.alt_text)
};
featuredOpuro.slug = '';

const featuredOpol = {
  url: str(FEATURED_OPOL.URL ?? FEATURED_OPOL.url),
  alt_text: str(FEATURED_OPOL.ALT ?? FEATURED_OPOL.alt_text)
};
featuredOpol.slug = '';

// v1.1.6 — validación condicionada por destino.
// Los campos editoriales comunes siguen siendo obligatorios.
// Los artefactos y medios específicos sólo se exigen si ese destino será creado.

const commonRequired = {
  title,
  slug,
  excerpt,
  primaryKeyword,
  tags
};

if (execution.create_opuro) {
  commonRequired.category = category;
}
if (execution.create_opol) {
  commonRequired.categoryOpol = categoryOpol;
}

const commonMissing = Object.entries(commonRequired)
  .filter(([, v]) => Array.isArray(v) ? v.length === 0 : !v)
  .map(([k]) => k);

if (commonMissing.length) {
  throw new Error(`OPMX MASTER incompleto para ${execution.destination}. Faltan campos comunes/seleccionados: ${commonMissing.join(', ')}`);
}

if (execution.create_opuro) {
  const requiredOpuro = {
    htmlFinal,
    heroOpuroUrl: heroOpuro.url,
    featuredOpuroUrl: featuredOpuro.url,
    featuredOpuroAlt: featuredOpuro.alt_text
  };

  const missingOpuro = Object.entries(requiredOpuro)
    .filter(([, v]) => !v)
    .map(([k]) => k);

  if (missingOpuro.length) {
    throw new Error(`OPMX MASTER incompleto para Oxígeno Puro. Faltan: ${missingOpuro.join(', ')}`);
  }

  const badHtml = [/^CONTENIDO_HTML_FINAL/i,/HTML_FINAL_COMPLETO/i,/INCLUIDO_EN_EL_JSON/i,/PLACEHOLDER/i,/TODO[_\s-]*HTML/i];
  if (badHtml.some(rx => rx.test(htmlFinal)) || !/<[a-z][\s\S]*>/i.test(htmlFinal)) {
